1	// Red-first fixtures for this pack's check, plus a guard on the pack manifest.
2	//
3	// The check reads its files through the engine's `ctx`, so the fixtures here are
4	// tiny in-memory contexts ({ files, read }) — no temp dirs, no mount, and the
5	// same shape the real runner passes (engine/checks/helpers/repo-context.mjs).
6	// The last rule test runs it against this repo's ACTUAL package.json and
7	// scripts/verify.sh, which is what makes the check a live gate rather than a
8	// self-fulfilling unit test.
9	
10	import { test } from "node:test";
11	import assert from "node:assert/strict";
12	import { readFileSync, existsSync } from "node:fs";
13	import { execFileSync } from "node:child_process";
14	import { fileURLToPath } from "node:url";
15	import path from "node:path";
16	
17	import pack from "./pack.mjs";
18	import rule from "./test-globs-in-step.mjs";
19	import verifyShSourceDirsRule from "./verify-sh-source-dirs.mjs";
20	import noStrayPackageJsonRule from "./no-stray-package-json.mjs";
21	import workerRestoresMainRule from "./worker-restores-main.mjs";
22	
23	const __dirname = path.dirname(fileURLToPath(import.meta.url));
24	const REPO = path.resolve(__dirname, "../../../..");
25	
26	/** The repo's real tracked files, for a live-gate test against actual content. */
27	function trackedFiles() {
28	  return execFileSync("git", ["ls-files"], { cwd: REPO, encoding: "utf8" })
29	    .split("\n")
30	    .filter(Boolean);
31	}
32	
33	const GLOBS = "plan/lib/__tests__/*.test.mjs .claudinite/local/packs/*/*.test.mjs";
34	
35	/** A context over an in-memory {path: string} map, matching the engine's ctx. */
36	function ctxOf(tree) {
37	  const files = Object.keys(tree);
38	  return { files, read: (p) => (p in tree ? tree[p] : null) };
39	}
40	
41	const verifyScript = (globs) => `#!/usr/bin/env bash
42	set -euo pipefail
43	
44	step "Unit tests — node --test"
45	# Keep in step with the "test" script in package.json.
46	node --test ${globs}
47	
48	step "JavaScript syntax — node --check"
49	`;
50	
51	const packageJson = (globs) =>
52	  JSON.stringify({ name: "edfringenow", scripts: { test: `node --test ${globs}`, verify: "bash scripts/verify.sh" } });
53	
54	test("identical glob lists produce no findings", () => {
55	  const out = rule.run(ctxOf({
56	    "package.json": packageJson(GLOBS),
57	    "scripts/verify.sh": verifyScript(GLOBS),
58	  }));
59	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
60	});
61	
62	test("the same globs in a different order still pass", () => {
63	  const out = rule.run(ctxOf({
64	    "package.json": packageJson(".claudinite/local/packs/*/*.test.mjs plan/lib/__tests__/*.test.mjs"),
65	    "scripts/verify.sh": verifyScript(GLOBS),
66	  }));
67	  assert.deepEqual(out, []);
68	});
69	
70	test("a glob added to package.json but not to verify.sh is reported", () => {
71	  // The exact regression this guards: a new local pack's pack.test.mjs is wired
72	  // into `npm test`, the verify.sh copy is forgotten, and CI never runs it.
73	  const out = rule.run(ctxOf({
74	    "package.json": packageJson(`${GLOBS} .claudinite/local/packs/edfringe/tasks/*/*.test.mjs`),
75	    "scripts/verify.sh": verifyScript(GLOBS),
76	  }));
77	  assert.equal(out.length, 1);
78	  assert.equal(out[0].rule, "edfringe-test-globs-in-step");
79	  assert.equal(out[0].severity, "blocking");
80	  assert.equal(out[0].file, "scripts/verify.sh");
81	  assert.match(out[0].what, /drifted apart/);
82	  assert.match(out[0].what, /only in package\.json: \.claudinite\/local\/packs\/edfringe\/tasks\/\*\/\*\.test\.mjs/);
83	  assert.ok(out[0].fix.includes("npm test"), "the fix must name the single-source escape hatch");
84	});
85	
86	test("a glob added to verify.sh but not to package.json is reported", () => {
87	  const out = rule.run(ctxOf({
88	    "package.json": packageJson(GLOBS),
89	    "scripts/verify.sh": verifyScript(`${GLOBS} scraper/__tests__/*.test.mjs`),
90	  }));
91	  assert.equal(out.length, 1);
92	  assert.match(out[0].what, /only in scripts\/verify\.sh: scraper\/__tests__\/\*\.test\.mjs/);
93	});
94	
95	test("verify.sh dropping `node --test` entirely is reported", () => {
96	  const out = rule.run(ctxOf({
97	    "package.json": packageJson(GLOBS),
98	    "scripts/verify.sh": "#!/usr/bin/env bash\nset -euo pipefail\nnode --check js/app.js\n",
99	  }));
100	  assert.equal(out.length, 1);
101	  assert.match(out[0].what, /runs no unit tests at all/);
102	});
103	
104	test("verify.sh delegating to `npm test` is single-sourced, so the check stands down", () => {
105	  const out = rule.run(ctxOf({
106	    "package.json": packageJson(GLOBS),
107	    "scripts/verify.sh": "#!/usr/bin/env bash\nset -euo pipefail\nnpm test\n",
108	  }));
109	  assert.deepEqual(out, []);
